Here is the recipe JSON:
{
  "recipe_name": "Classic Cheese Pizza",
  "ingredients": [
    "1 1/2 cups warm water",
    "1 tablespoon sugar",
    "2 teaspoons active dry yeast",
    "3 1/2 cups all-purpose flour",
    "1 teaspoon salt",
    "2 tablespoons olive oil",
    "1/2 cup pizza sauce",
    "1 cup shredded mozzarella cheese",
    "1/2 cup shredded parmesan cheese",
    "Toppings of your choice (e.g. pepperoni, bell peppers, onions, mushrooms)"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "Combine warm water, sugar, and yeast. Let it sit for 5-10 minutes until yeast is activated.",
      "time": "10 minutes",
      "tip": "Make sure the water is not too hot, as it can kill the yeast."
    },
    {
      "step_number": 2,
      "instruction": "Add flour, salt, and olive oil to the yeast mixture. Mix until a dough forms.",
      "time": "5 minutes",
      "tip": "Use a stand mixer with a dough hook attachment for easier mixing."
    },
    {
      "step_number": 3,
      "instruction": "Knead the dough for 5-10 minutes until it becomes smooth and elastic.",
      "time": "10 minutes",
      "tip": "You can also knead the dough by hand if you don't have a stand mixer."
    },
    {
      "step_number": 4,
      "instruction": "Place the dough in a greased bowl, cover it with a damp cloth, and let it rise in a warm place for 1-2 hours.",
      "time": "1-2 hours",
      "tip": "Make sure the dough is in a warm, draft-free place to help it rise."
    },
    {
      "step_number": 5,
      "instruction": "Preheat the oven to 425\u00b0F (220\u00b0C). Punch down the dough and shape it into a circle or rectangle.",
      "time": "10 minutes",
      "tip": "Use a pizza stone or baking sheet to help the crust cook evenly."
    },
    {
      "step_number": 6,
      "instruction": "Spread the pizza sauce over the dough, leaving a small border around the edges.",
      "time": "2 minutes",
      "tip": "Use a high-quality pizza sauce for the best flavor."
    },
    {
      "step_number": 7,
      "instruction": "Sprinkle the mozzarella and parmesan cheese over the sauce.",
      "time": "2 minutes",
      "tip": "Use a combination of mozzarella and parmesan cheese for the best flavor."
    },
    {
      "step_number": 8,
      "instruction": "Add your desired toppings and bake the pizza in the preheated oven for 15-20 minutes.",
      "time": "15-20 minutes",
      "tip": "Keep an eye on the pizza while it's baking to avoid overcooking."
    }
  ]
}
